mkdir -p ~/development/.tmp/stallion-locator && cat > ~/development/.tmp/stallion-locator/proof.mjs <<'EOF'
import { createRequire } from "node:module";
import { renameSync, readdirSync } from "node:fs";
import { join } from "node:path";
const WT = "/home/mvhenten/development/stallion-worktrees/locator";
const require = createRequire(join(WT, "package.json"));
const { chromium } = require("playwright");
const { routeAccessHeaders } = await import(join(WT, "npm-scripts/env.mjs"));

const OUT = "/home/mvhenten/development/.tmp/stallion-locator";
const ORIGIN = "https://stallion.matthijs-f49.workers.dev";
const id = `locator${Date.now().toString(36)}`;
const url = `${ORIGIN}/b/${id}`;
const VIEWPORT = { width: 1280, height: 800 };

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({
  viewport: VIEWPORT,
  deviceScaleFactor: 1,
  recordVideo: { dir: join(OUT, "raw"), size: VIEWPORT },
});
await routeAccessHeaders(context, ORIGIN);
await context.addInitScript(() => {
  window.__raf = 0;
  const raf = window.requestAnimationFrame.bind(window);
  window.requestAnimationFrame = (cb) => {
    window.__raf++;
    return raf(cb);
  };
});
const page = await context.newPage();
const errors = [];
page.on("console", (m) => m.type() === "error" && errors.push(m.text()));
page.on("pageerror", (e) => errors.push(String(e)));

await page.goto(url, { waitUntil: "load" });
await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
await page.waitForTimeout(1500);

const cx = 640, cy = 400;
await page.mouse.move(cx - 40, cy - 30);
await page.mouse.down();
for (let i = 1; i <= 20; i++) await page.mouse.move(cx - 40 + i * 4, cy - 30 + i * 3);
await page.mouse.up();
await page.waitForTimeout(800);

const level = async () =>
  Number(
    (await page.locator("[aria-label^='Zoom level ']").first().getAttribute("aria-label")).replace(
      "Zoom level ",
      "",
    ),
  );
await page.mouse.move(cx, cy);
for (let i = 0; i < 80 && (await level()) < 4; i++) {
  await page.mouse.wheel(0, 100);
  await page.waitForTimeout(60);
}
const reached = await level();
await page.waitForTimeout(600);

const more = page.getByRole("button", { name: "More tools" });
if (await more.isVisible()) await more.click();
await page.getByRole("button", { name: "Select tool" }).first().click();
await page.waitForTimeout(300);

await page.mouse.move(cx + 1100 - 640, cy + 350 - 400);
await page.mouse.move(cx + 80, cy);
const before = await page.evaluate(() => window.__raf);
const shots = [];
for (const [i, wait] of [150, 300, 300].entries()) {
  await page.waitForTimeout(wait);
  const path = join(OUT, `ripple-${i + 1}.png`);
  await page.screenshot({ path, clip: { x: cx - 160, y: cy - 120, width: 320, height: 240 } });
  shots.push(path);
}
await page.waitForTimeout(1500);
const during = (await page.evaluate(() => window.__raf)) - before;

await page.mouse.move(cx + 3, cy + 1);
await page.waitForTimeout(700);
const onObject0 = await page.evaluate(() => window.__raf);
await page.waitForTimeout(1000);
const onObject = (await page.evaluate(() => window.__raf)) - onObject0;
await page.screenshot({ path: join(OUT, "on-object.png"), clip: { x: cx - 160, y: cy - 120, width: 320, height: 240 } });

await page.mouse.move(1200, 150);
await page.waitForTimeout(800);
const idle0 = await page.evaluate(() => window.__raf);
await page.waitForTimeout(2000);
const idle = (await page.evaluate(() => window.__raf)) - idle0;

const video = page.video();
await context.close();
await browser.close();
const raw = await video.path();
renameSync(raw, join(OUT, "ripple.webm"));
console.log(JSON.stringify({ url, reached, during, onObject, idle, errors, shots, video: join(OUT, "ripple.webm") }, null, 2));
EOF
